INSERT INTO material(disciplina_id,titulo,descricao,tipo,referencia_externa,fonte_monitor_virtual) SELECT id,'Aula 0 — Estrutura de Dados Avançada','PDF original das aulas; fonte do Monitor Virtual.','SLIDE_AULA','local:materiais_academicos/periodo_03/estrutura_de_dados_avancada/Aula_0.pdf',TRUE FROM disciplina d WHERE d.slug='estrutura_de_dados_avancada' AND NOT EXISTS(SELECT 1 FROM material m WHERE m.disciplina_id=d.id AND m.referencia_externa='local:materiais_academicos/periodo_03/estrutura_de_dados_avancada/Aula_0.pdf');
